import {icon3D as I} from './icons.js';
const AXES=['x','y','z'];
const FACES=[['right','x',1,'#1e3dff','Blue'],['left','x',-1,'#ff3acb','Pink'],['top','y',1,'#a8ff00','Lime'],['bottom','y',-1,'#ffb800','Gold'],['front','z',1,'#00cde8','Cyan'],['back','z',-1,'#8b64ed','Violet']];
const BANDS=['6-8','9-11','12-14'];
const KEY='zuno-cube-progress-v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class CubePuzzle{
 constructor(size=3){if(![2,3].includes(size))throw Error('Cube size must be 2 or 3');this.size=size;this.edge=(size-1)/2;this.reset()}
 reset(){this.cubies=[];let id=0;for(let x=-this.edge;x<=this.edge;x++)for(let y=-this.edge;y<=this.edge;y++)for(let z=-this.edge;z<=this.edge;z++)this.cubies.push({id:id++,home:{x,y,z},pos:{x,y,z},basis:[{x:1,y:0,z:0},{x:0,y:1,z:0},{x:0,y:0,z:1}]});this.history=[];this.redoStack=[]}
 static rotate(v,axis,direction){const {x,y,z}=v,d=direction;if(axis==='x')return{x,y:-d*z,z:d*y};if(axis==='y')return{x:d*z,y,z:-d*x};if(axis==='z')return{x:-d*y,y:d*x,z};throw Error('Invalid axis')}
 move(input,track=true){const {axis,layer,direction}=input;if(!AXES.includes(axis)||!Array.from({length:this.size},(_,i)=>i-this.edge).includes(layer)||![-1,1].includes(direction))throw Error('Invalid cube move');for(const c of this.cubies)if(c.pos[axis]===layer){c.pos=CubePuzzle.rotate(c.pos,axis,direction);c.basis=c.basis.map(v=>CubePuzzle.rotate(v,axis,direction))}if(track){this.history.push({...input});this.redoStack=[]}return input}
 undo(){const m=this.history.pop();if(!m)return null;const inv={...m,direction:-m.direction};this.move(inv,false);this.redoStack.push(m);return inv}
 redo(){const m=this.redoStack.pop();if(!m)return null;this.move(m,false);this.history.push(m);return m}
 stickers(){const result=[];for(const c of this.cubies)for(let f=0;f<FACES.length;f++){const[,axis,sign]=FACES[f];if(c.home[axis]!==sign*this.edge)continue;const vector=c.basis[AXES.indexOf(axis)],normal=Object.fromEntries(AXES.map(k=>[k,vector[k]*sign]));const target=FACES.findIndex(([,a,s])=>normal[a]===s);result.push({face:target,colour:f,pos:c.pos})}return result}
 isSolved(){const groups=Array.from({length:6},()=>[]);for(const s of this.stickers())groups[s.face].push(s.colour);return groups.every(g=>g.length===this.size*this.size&&g.every(c=>c===g[0]))}
}
export function cubeConfig(age='9-11',level=1){if(!BANDS.includes(age))age='9-11';level=Math.max(1,Math.min(20,Math.trunc(Number(level)||1)));const size=age==='6-8'&&level<=10?2:3;const base=age==='6-8'?1:age==='9-11'?2:3;return{age,level,size,turns:Math.min(14,base+Math.floor((level-1)/2)),guided:age==='6-8'||level<=4}}
export function scrambleFor(config){let seed=config.level*1031+BANDS.indexOf(config.age)*4177+23;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};const moves=[],edge=(config.size-1)/2;for(let i=0;i<config.turns;i++){let axis,layer;do{axis=AXES[Math.floor(random()*3)];layer=random()<.5?-edge:edge}while(moves.length&&moves.at(-1).axis===axis&&moves.at(-1).layer===layer);moves.push({axis,layer,direction:random()<.5?-1:1})}return moves}
function progress(){try{const d=JSON.parse(localStorage.getItem(KEY)||'{}');return d&&typeof d==='object'&&!Array.isArray(d)?d:{}}catch{return{}}}
export function cubeUnlocked(age,level,admin=false){if(admin||level===1)return true;const stored=progress()[age],done=Array.isArray(stored)?stored.filter(n=>Number.isInteger(n)&&n>=1&&n<=20):[];return Array.from({length:level-1},(_,i)=>i+1).every(n=>done.includes(n))}
function coordinate(sticker,edge){const p=sticker.pos;switch(sticker.face){case 0:return[edge-p.y,edge-p.z];case 1:return[edge-p.y,p.z+edge];case 2:return[p.z+edge,p.x+edge];case 3:return[edge-p.z,p.x+edge];case 4:return[edge-p.y,p.x+edge];case 5:return[edge-p.y,edge-p.x]}}
export function faceGrid(puzzle){const grids=Array.from({length:6},()=>Array(puzzle.size*puzzle.size).fill(-1));for(const s of puzzle.stickers()){const[row,col]=coordinate(s,puzzle.edge);grids[s.face][row*puzzle.size+col]=s.colour}return grids}
function cubeHTML(puzzle){const grids=faceGrid(puzzle);return `<div class="twist-cube" style="--cube-count:${puzzle.size}">${FACES.map(([name,,,,colour],face)=>`<div class="twist-face twist-${name}" aria-label="${colour} starting face">${grids[face].map(c=>`<span class="twist-sticker sticker-${c}" style="--sticker-colour:${FACES[c][3]}" title="${FACES[c][4]}"><span aria-hidden="true">${['●','✚','◆','▲','═','✦'][c]}</span><span class="sr-only">${FACES[c][4]}</span></span>`).join('')}</div>`).join('')}</div>`}
export function cubePage(age='9-11',level=1,{admin=false}={}){const c=cubeConfig(age,level);if(!cubeUnlocked(c.age,c.level,admin))return `<section class="cube-lab"><a class="back" href="#/play">${I('arrow-left')}All games</a><div class="empty"><h1>This cube is waiting for you.</h1><p>Finish the earlier Cube Lab levels to unlock this challenge.</p><a class="button" href="#/play/cube/1">Start at level 1 ${I('play')}</a></div></section>`;const p=new CubePuzzle(c.size);scrambleFor(c).forEach(m=>p.move(m));return `<section class="cube-lab" data-cube-age="${c.age}" data-cube-level="${c.level}"><a class="back" href="#/play">${I('arrow-left')}All games</a><header class="cube-heading"><div><span class="eyebrow">ZUNO CUBE LAB · AGES ${c.age}</span><h1>A little twist.<br>A bright idea.</h1><p>Level ${c.level} of 20 · ${c.size} × ${c.size} · ${c.turns} scramble ${c.turns===1?'turn':'turns'}</p></div><span class="cube-level-mark">${I('puzzle')}<strong>${c.level}</strong></span></header><div class="cube-workspace"><div class="cube-play-panel"><div class="cube-stage" id="cube-stage" tabindex="0" aria-label="Interactive 3D twist cube. Use face turn buttons below; arrow keys rotate the view.">${cubeHTML(p)}</div><div class="cube-view-controls"><button class="chip" data-cube-view="left" aria-label="Look at the cube from the left">${I('arrow-left')}Look left</button><button class="chip" data-cube-view="right" aria-label="Look at the cube from the right">Look right${I('arrow-right')}</button><button class="chip" data-cube-view="up" aria-label="Look above the cube">Look above</button></div><p class="cube-state" id="cube-state" role="status">Can you make every side one colour? Shapes help you tell the colours apart.</p><div class="cube-counters"><span><strong id="cube-moves">0</strong> your turns</span><span><strong id="cube-hints">0</strong> hints</span></div></div><aside class="cube-control-panel"><h2>Choose a side. Turn it.</h2><p>Clockwise means turning as if you were looking straight at that side. You can always undo a move.</p><div class="cube-turn-buttons">${FACES.map(([name,axis,sign,colour,label])=>`<div class="cube-turn-row"><span class="cube-face-dot" style="--sticker-colour:${colour}" aria-hidden="true"></span><strong>${name[0].toUpperCase()+name.slice(1)}</strong><button class="chip" data-cube-turn="${name}" data-direction="1" aria-label="Turn ${name} side clockwise">Turn ↻</button><button class="chip" data-cube-turn="${name}" data-direction="-1" aria-label="Turn ${name} side anticlockwise">Back ↺</button></div>`).join('')}</div><div class="cube-tool-row"><button class="chip" data-cube-action="undo">${I('rotate-ccw')}Undo</button><button class="chip" data-cube-action="hint">${I('lightbulb')}A clue</button><button class="chip" data-cube-action="reset">${I('rotate-ccw')}Restart level</button></div><div class="cube-clue" id="cube-clue" role="status">${c.guided?'Try noticing one side at a time. The first challenges need only a few reverse turns.':'Plan a short sequence, test it, then notice which stickers moved together.'}</div><div class="cube-finished" id="cube-finished" hidden><h2>Every side found its colour!</h2><p>You solved this twist challenge. Your next level is ready.</p>${c.level<20?`<a class="button" href="#/play/cube/${c.level+1}">Level ${c.level+1} ${I('arrow-right')}</a>`:'<a class="button" href="#/play">All 20 explored! Back to games</a>'}</div></aside></div><nav class="cube-levels" aria-label="Cube levels">${Array.from({length:20},(_,i)=>{const l=i+1,unlocked=cubeUnlocked(c.age,l,admin);return `<a ${unlocked?`href="#/play/cube/${l}"`:'aria-disabled="true"'} class="${l===c.level?'active':''}">${l}${unlocked?'':I('lock-keyhole')}</a>`}).join('')}</nav><p class="cube-small">Twist, explore and solve in ZUNO colours. Progress stays in this browser, separately for each reading band.</p></section>`}
export function mountCube({onComplete=()=>{},toast=()=>{},reduced=false}={}){const root=document.querySelector('.cube-lab[data-cube-age]');if(!root)return()=>{};const c=cubeConfig(root.dataset.cubeAge,root.dataset.cubeLevel),p=new CubePuzzle(c.size),scramble=scrambleFor(c);scramble.forEach(m=>p.move(m));const stage=root.querySelector('#cube-stage');let moves=0,hints=0,view=-33,tilt=-25,done=false,dead=false,trail=scramble.map(m=>({...m})),playerMoves=[];
 const trace=m=>{const last=trail.at(-1);if(last&&last.axis===m.axis&&last.layer===m.layer&&last.direction===-m.direction)trail.pop();else trail.push({...m})};const abort=new AbortController();
 const update=()=>{if(dead)return;stage.innerHTML=cubeHTML(p);const cube=stage.firstElementChild;cube.style.transform=`rotateX(${tilt}deg) rotateY(${view}deg)`;root.querySelector('#cube-moves').textContent=moves;root.querySelector('#cube-hints').textContent=hints;root.querySelector('[data-cube-action="undo"]').disabled=!playerMoves.length||done;if(!done&&p.isSolved()){done=true;const d=progress(),old=Array.isArray(d[c.age])?d[c.age]:[];d[c.age]=[...new Set([...old,c.level])];try{localStorage.setItem(KEY,JSON.stringify(d))}catch{toast('Solved! This browser could not save your cube progress.')}root.querySelector('#cube-state').textContent='Solved! Every side is one colour.';root.querySelector('#cube-finished').hidden=false;root.querySelectorAll('[data-cube-turn]').forEach(b=>b.disabled=true);const next=root.querySelector(`.cube-levels a:nth-child(${c.level+1})`);if(next){next.href=`#/play/cube/${c.level+1}`;next.removeAttribute('aria-disabled');next.innerHTML=String(c.level+1)}onComplete({game:'cube',age:c.age,level:c.level,moves,hints});}else if(!done)root.querySelector('#cube-state').textContent=moves?`Keep noticing. ${moves} ${moves===1?'turn':'turns'} made; take your time.`:'Can you make every side one colour? Shapes help you tell the colours apart.';};
 const turn=(m)=>{if(done)return;p.move(m);playerMoves.push({...m});trace(m);moves++;update();if(!reduced&&stage.animate)stage.animate([{opacity:.65,filter:'brightness(1.2)'},{opacity:1,filter:'brightness(1)'}],{duration:180});};
 root.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.cubeTurn){const f=FACES.find(f=>f[0]===button.dataset.cubeTurn);turn({axis:f[1],layer:f[2]*p.edge,direction:-Number(button.dataset.direction)*f[2]})}else if(button.dataset.cubeView){if(button.dataset.cubeView==='left')view-=90;else if(button.dataset.cubeView==='right')view+=90;else tilt=tilt===-25?-65:-25;update()}else if(button.dataset.cubeAction==='undo'&&!done&&playerMoves.length){const m=playerMoves.pop(),inverse={...m,direction:-m.direction};p.move(inverse);trace(inverse);moves++;update()}else if(button.dataset.cubeAction==='reset'){done=false;moves=0;hints=0;p.reset();scramble.forEach(m=>p.move(m));trail=scramble.map(m=>({...m}));playerMoves=[];root.querySelector('#cube-finished').hidden=true;root.querySelectorAll('[data-cube-turn]').forEach(b=>b.disabled=false);root.querySelector('#cube-clue').textContent='Same challenge, fresh start. Try a different plan.';update()}else if(button.dataset.cubeAction==='hint'&&!done){const last=trail.at(-1);if(last){hints++;const f=FACES.find(f=>f[1]===last.axis&&f[2]*p.edge===last.layer),direction=last.direction*f[2];root.querySelector('#cube-clue').textContent=`A useful next step: turn the ${f[0]} (${f[4].toLowerCase()}) side ${direction===1?'clockwise (Turn ↻)':'anticlockwise (Back ↺)'}. This reverses one turn in your current trail.`;update()}}},{signal:abort.signal});
 stage.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')view-=90;if(e.key==='ArrowRight')view+=90;if(e.key==='ArrowUp')tilt=Math.max(-75,tilt-20);if(e.key==='ArrowDown')tilt=Math.min(65,tilt+20);update()},{signal:abort.signal});update();return()=>{dead=true;abort.abort()}}
